def make_question(index,row):
 tag,prompt,options,answer,reason=row
 # 讓答案位置分布為 A2/B3/C3/D2；只調整位置，不改動選項語義。
 target_letters=["A","B","C","D","B","C","D","A","C","B"]
 target=target_letters[index-1]
 distractors=[t for t in options if t != answer]
 ordered=[]; di=0
 for letter in ["A","B","C","D"]:
  if letter == target: ordered.append(answer)
  else: ordered.append(distractors[di]); di += 1
 opts=[{"id":chr(65+i),"text":t} for i,t in enumerate(ordered)]; aid=target
 refs=[{"url":u,"title":f"{t}；僅研究公開題型與能力方向，未複製原題。","year":"113-114","subject":"social","locator":l,"observedPattern":"公立學校社會科公開試題常見的冷戰、東亞競合、代理戰爭、外交與多重資料推理能力，經本題重新設計。","reuseDecision":"pattern-only","status":"recorded","locatorLevel":"paper"} for u,t,l in SOURCES]
 steps=[f"讀題定位：圈出「{tag}」並標記陣營、地方行動者、外交、戰爭或資料類型。",f"整理證據：分開全球結構、地方政治、同盟利益與民眾生活；本題核心是「{reason}」。",f"核對正解：選項 {aid}「{answer}」能同時回應題幹資料與冷戰東亞競合的歷史推理。","排除誘答：檢查是否把大國因素當成唯一原因，或把合作、對立與宣傳簡化成全有全無。","結論回查：確認國內、區域、全球尺度、時間差異與資料限制都已納入。"]
 return {"id":f"question-social-content-hist-lb-iv-1-{index}","subject":"social","type":"single-choice","prompt":prompt,"options":opts,"knowledgeIds":["kg-social-content-hist-lb-iv-1"],"difficulty":"medium","answer":{"value":aid,"explanation":reason},"provenance":{"origin":"original","license":"All rights reserved","sourceUrl":SOURCES[0][0],"sourceLocator":"高雄市立鹽埕國中三年級社會科公開段考；本題只研究公開試題能力結構與資料型態。","authoringNote":"依官方課綱、單元 KG 與三個公立學校公開來源的題型方向，獨立改寫兩極對立、韓戰分裂、代理戰爭、同盟援助、威權發展、宣傳日常、外交轉向、臺海區域、經濟競合與多重資料情境；未複製原文、選項、圖表或答案；待第二輪 AI／Terra 內容複核。"},"reviewStatus":"draft","updatedAt":"2026-09-09","lessonId":"lesson-social-content-hist-lb-iv-1","examPatternRefs":refs,"solutionStrategy":"先區分冷戰全球結構與東亞地方行動，再比較戰爭、同盟、政權、宣傳、臺海與經濟互賴，最後以多重來源檢驗大國中心敘事。","solutionSteps":steps}

